#include <iostream>
using namespace std;

// 在 a[0..n-1] 中找 x，找到返回下标，否则返回 -1
int binarySearch(int a[], int n, int x) {
    int L = 0, R = n - 1;
    while (L <= R) {
        int mid = (L + R) / 2;
        if (a[mid] == x) return mid;
        if (a[mid] < x) L = mid + 1;
        else R = mid - 1;
    }
    return -1;
}

