#include <iostream>
#include <algorithm>
using namespace std;

int main() {
    int W, n, w[30005];
    cin >> W >> n;
    for (int i = 0; i < n; i++) cin >> w[i];
    sort(w, w + n);
    int L = 0, R = n - 1, ans = 0;
    while (L <= R) {
        if (w[L] + w[R] <= W) { L++; R--; }
        else R--;
        ans++;
    }
    cout << ans << endl;
    return 0;
}

